parameters.jsCode:
// Aggregate the four data sources into a single payload for Claude.
// In n8n, items from upstream nodes are referenced by name: $('NodeName').all()
// We defensively handle empty/error responses from the mocked sources.

const prs = $('GitHub: PRs last 7d').first()?.json?.items || [];
const issues = $('GitHub: Issues last 7d').first()?.json?.items || [];

const linearRaw = $('Linear: tickets last 7d (mock if no key)').first()?.json;
const linearNodes = (linearRaw && linearRaw.data && linearRaw.data.issues && linearRaw.data.issues.nodes) || null;
const linear = linearNodes === null ? null : linearNodes; // null = mocked/unavailable

const slackRaw = $('Slack: #dev last 7d (mock if no token)').first()?.json;
const slack = (slackRaw && slackRaw.ok && slackRaw.messages) ? slackRaw.messages : null;

const date = $('Set Date Range').first().json;

// Light shape normalization
const slimPRs = prs.map(p => ({
  number: p.number,
  title: p.title,
  state: p.state,
  merged: !!p.pull_request?.merged_at,
  user: p.user?.login,
  url: p.html_url,
  created_at: p.created_at,
  closed_at: p.closed_at
}));

const slimIssues = issues.map(i => ({
  number: i.number,
  title: i.title,
  state: i.state,
  user: i.user?.login,
  url: i.html_url,
  labels: (i.labels || []).map(l => l.name),
  created_at: i.created_at,
  closed_at: i.closed_at
}));

const summary = {
  week: date.week_label,
  github: {
    prs_total: slimPRs.length,
    prs_merged: slimPRs.filter(p => p.merged).length,
    prs_open: slimPRs.filter(p => p.state === 'open').length,
    prs_closed: slimPRs.filter(p => p.state === 'closed' && !p.merged).length,
    prs: slimPRs.slice(0, 30),
    issues_total: slimIssues.length,
    issues_opened: slimIssues.filter(i => i.created_at >= date.since_date).length,
    issues_closed: slimIssues.filter(i => i.state === 'closed').length,
    issues: slimIssues.slice(0, 30)
  },
  linear: linear, // null = unavailable, array = real
  slack: slack,   // null = unavailable, array = real
  sources_status: {
    github: 'ok',
    linear: linear === null ? 'mocked_or_unavailable' : 'ok',
    slack: slack === null ? 'mocked_or_unavailable' : 'ok'
  }
};

return [{ json: { aggregated: summary, _week_label: date.week_label, _github_owner: date.github_owner, _github_repo: date.github_repo, _github_target_repo: date.github_target_repo } }];

// Extract the markdown text from the Claude response and prepare for publishing.
const resp = $json;

if (!resp || !resp.content || !Array.isArray(resp.content) || resp.content.length === 0) {
  throw new Error('Unexpected Claude response shape: ' + JSON.stringify(resp).slice(0, 500));
}

const text = resp.content
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n');

const usage = resp.usage || {};
const inTokens = usage.input_tokens || 0;
const outTokens = usage.output_tokens || 0;

// Cost estimate for claude-3-5-sonnet-latest (as of 2025): $3/M input, $15/M output
const costUSD = (inTokens * 3 / 1_000_000) + (outTokens * 15 / 1_000_000);

return [{
  json: {
    summary_md: text,
    title: 'Weekly Dev Summary — ' + $('Code: Build prompt').first().json.week_label,
    week_label: $('Code: Build prompt').first().json.week_label,
    github_owner: $('Code: Build prompt').first().json.github_owner,
    github_repo: $('Code: Build prompt').first().json.github_repo,
    github_target_repo: $('Code: Build prompt').first().json.github_target_repo,
    usage: { in: inTokens, out: outTokens, cost_usd: costUSD },
    claude_model: resp.model || 'claude-3-5-sonnet-latest',
    claude_stop_reason: resp.stop_reason || null
  }
}];

